```kotlin
// ❌ في نظام XML التقليدي: تعديل أمري عرضة لتضارب الحالات:
fun renderState(state: UiState) {
    when (state) {
        is UiState.Loading -> {
            binding.progressBar.visibility = View.VISIBLE
            binding.textView.visibility = View.GONE // إذا نسيت هذا السطر يظل النص القديم ظاهراً!
        }
        is UiState.Success -> {
            binding.progressBar.visibility = View.GONE
            binding.textView.visibility = View.VISIBLE
            binding.textView.text = state.data
        }
    }
}

// ✅ في Jetpack Compose: وصف تصريحي حتمي، يستحيل معه تضارب الحالة:
@Composable
fun UserProfileScreen(uiState: UiState) {
    when (uiState) {
        is UiState.Loading -> CircularProgressIndicator()
        is UiState.Success -> Text(text = uiState.data)
        is UiState.Error -> Text(text = uiState.message, color = MaterialTheme.colorScheme.error)
    }
}
```

كيف يؤدي كود يحتوي على Side-Effect داخل دالة Composable إلى كوارث أداء وكيفية علاجه:
```kotlin
// ❌ كود كارثي: تشغيل Side-Effect مباشرة داخل جسم الـ Composable:
@Composable
fun BadUserCounter(count: Int) {
    // 💥 كارثة: في كل مرة يعاد فيها رسم الشاشة (Recomposition)، يتم إرسال طلب تحليلات جديد!
    AnalyticsTracker.logEvent("screen_viewed")

    Text(text = "Count: $count")
}

// ✅ كود سليم: عزل الـ Side-Effects داخل Effect Handlers المخصصة:
@Composable
fun GoodUserCounter(count: Int) {
    // يتم استدعاؤه مرة واحدة فقط عند دخول الـ Composable لأول مرة:
    LaunchedEffect(Unit) {
        AnalyticsTracker.logEvent("screen_viewed")
    }

    Text(text = "Count: $count")
}
```

كود يوضح الفرق بين دالة يمكن تخطيها ودالة يُعاد تركيبها دائماً بسبب `List` غير مستقرة:
```kotlin
// ❌ دالة تفشل في الـ Skipping بسبب استخدام List<String> القياسية:
@Composable
fun UnskippableUserList(users: List<String>, onUserClick: (String) -> Unit) {
    // Compose Compiler يعتبر List نوعاً Unstable، لذا يُعاد تنفيذ هذه الدالة في كل recomposition للأب!
    LazyColumn {
        items(users) { user ->
            Text(text = user, modifier = Modifier.clickable { onUserClick(user) })
        }
    }
}

// ✅ دالة مستقرة تقبل التخطي (Skippable) باستخدام ImmutableList:
import kotlinx.collections.immutable.ImmutableList

@Composable
fun SkippableUserList(users: ImmutableList<String>, onUserClick: (String) -> Unit) {
    // هنا يعلم المترجم أن users مستقرة تماماً، فإذا لم تتغير القائمة، يتم تخطي الدالة 100%:
    LazyColumn {
        items(users) { user ->
            Text(text = user, modifier = Modifier.clickable { onUserClick(user) })
        }
    }
}
```

