@Composable
fun CheckoutScreen(viewModel: CheckoutViewModel = viewModel()) {
    // 1. ViewModel State: بيانات الـ Business والـ Backend تنجو من التدوير والـ Navigation:
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()

    // 2. rememberSaveable: حالة واجهة مستخدم خاصة بالشاشة تنجو من تدوير الهاتف وموت العملية:
    var promoCodeInput by rememberSaveable { mutableStateOf("") }

    // 3. remember: كائن مؤقت خاص بالرسم أو الحسابات يضيع عند التدوير ويعاد إنشاؤه بسهولة:
    val currencyFormatter = remember(Locale.getDefault()) {
        NumberFormat.getCurrencyInstance(Locale.getDefault())
    }

    CheckoutContent(
        total = currencyFormatter.format(uiState.totalAmount),
        promoCode = promoCodeInput,
        onPromoChange = { promoCodeInput = it }
    )
}
```

تطبيق نمط UDF بشكل قياسي في شاشة Compose:
```kotlin
// 1. تمثيل الـ State كبيانات تتدفق للأسفل:
data class CounterUiState(val count: Int = 0, val isMaxReached: Boolean = false)

// 2. تمثيل الأحداث التي تتدفق للأعلى:
sealed interface CounterEvent {
    data object Increment : CounterEvent
    data object Decrement : CounterEvent
}

// 3. المكون البصري: State Flows Down, Events Flow Up:
@Composable
fun CounterWidget(
    state: CounterUiState,
    onEvent: (CounterEvent) -> Unit,
    modifier: Modifier = Modifier
) {
    Row(modifier = modifier, verticalAlignment = Alignment.CenterVertically) {
        Button(onClick = { onEvent(CounterEvent.Decrement) }) { Text("-") }
        Text(text = "Count: ${state.count}", modifier = Modifier.padding(horizontal = 16.dp))
        Button(
            onClick = { onEvent(CounterEvent.Increment) },
            enabled = !state.isMaxReached
        ) { Text("+") }
    }
}
```

