أمثلة توضح متى وأين تستخدم كل أداة من أدوات الـ Side Effects الأربعة:
```kotlin
@Composable
fun MediaScreen(
    mediaId: String,
    onCompleted: () -> Unit
) {
    val snackbarHostState = remember { SnackbarHostState() }
    val coroutineScope = rememberCoroutineScope()

    // 1. LaunchedEffect: جلب بيانات أو مهمة suspend مرتبطة بالـ mediaId:
    LaunchedEffect(mediaId) {
        analytics.trackMediaOpened(mediaId)
    }

    // 2. DisposableEffect: اشتراك في خدمة خارجية يحتاج تنظيفاً إلزامياً:
    DisposableEffect(Unit) {
        val listener = ScreenWakeLock.acquire()
        onDispose {
            listener.release() // تنظيف فوري عند مغادرة الـ Composable
        }
    }

    // 3. SideEffect: مزامنة حالة داخلية مع كائن خارجي بعد كل Recomposition ناجح:
    SideEffect {
        externalTracker.lastRenderTimestamp = System.currentTimeMillis()
    }

    // 4. rememberCoroutineScope: إطلاق كوروتين في استجابة لحدث نقر المستخدم:
    Button(onClick = {
        coroutineScope.launch {
            snackbarHostState.showSnackbar("Media saved!")
            onCompleted()
        }
    }) {
        Text("Save")
    }
}
```

مقارنة عملية توضح متى نستخدم Unit ومتى نستخدم Dynamic Key:
```kotlin
// ❌ خطأ: استخدام Unit مع بارامتر ديناميكي؛ عند اختيار مستخدم آخر لن يتم تحديث البيانات:
@Composable
fun BadUserProfile(userId: String) {
    LaunchedEffect(Unit) {
        // 💥 إذا تغير userId لن يعمل هذا الكود مرة ثانية!
        loadUserData(userId)
    }
}

// ✅ الكود السليم: تمرير userId كـ Key؛ عند تغير الـ ID يُلغى الطلب القديم ويبدأ الجديد:
@Composable
fun GoodUserProfile(userId: String) {
    LaunchedEffect(userId) {
        // يُلغى الطلب السابق ويبدأ طلب المستخدم الجديد فوراً:
        loadUserData(userId)
    }
}

// ✅ استخدام سليم لـ Unit: مهام لا تعتمد على أي متغير وتعمل مرة واحدة فقط:
@Composable
fun SplashScreen(onTimeout: () -> Unit) {
    LaunchedEffect(Unit) {
        delay(2000)
        onTimeout()
    }
}
